#include <stdio.h>
#include <stdlib.h>
#include <math.h>
#include "nanovg.h"
#define NANOVG_GL3_IMPLEMENTATION
#include "nanovg_gl.h"
int main(int argc,char**argv){if(argc!=2)return 1;CGLPixelFormatAttribute attrs[]={kCGLPFAOpenGLProfile,(CGLPixelFormatAttribute)kCGLOGLPVersion_3_2_Core,kCGLPFAColorSize,(CGLPixelFormatAttribute)24,kCGLPFAAccelerated,(CGLPixelFormatAttribute)0};CGLPixelFormatObj fmt;GLint count;CGLContextObj context;if(CGLChoosePixelFormat(attrs,&fmt,&count)||CGLCreateContext(fmt,NULL,&context))return 2;CGLDestroyPixelFormat(fmt);CGLSetCurrentContext(context);GLuint fb,tex,stencil;glGenFramebuffers(1,&fb);glBindFramebuffer(GL_FRAMEBUFFER,fb);glGenTextures(1,&tex);glBindTexture(GL_TEXTURE_2D,tex);glTexImage2D(GL_TEXTURE_2D,0,GL_RGBA8,512,512,0,GL_RGBA,GL_UNSIGNED_BYTE,NULL);glFramebufferTexture2D(GL_FRAMEBUFFER,GL_COLOR_ATTACHMENT0,GL_TEXTURE_2D,tex,0);glGenRenderbuffers(1,&stencil);glBindRenderbuffer(GL_RENDERBUFFER,stencil);glRenderbufferStorage(GL_RENDERBUFFER,GL_DEPTH24_STENCIL8,512,512);glFramebufferRenderbuffer(GL_FRAMEBUFFER,GL_DEPTH_STENCIL_ATTACHMENT,GL_RENDERBUFFER,stencil);if(glCheckFramebufferStatus(GL_FRAMEBUFFER)!=GL_FRAMEBUFFER_COMPLETE)return 3;NVGcontext*vg=nvgCreateGL3(NVG_ANTIALIAS|NVG_STENCIL_STROKES);if(!vg)return 4;unsigned char* pixels=malloc(512*512*4);for(int frame=0;frame<3;frame++){glViewport(0,0,512,512);glClearColor(.043,.086,.145,1);glClear(GL_COLOR_BUFFER_BIT|GL_STENCIL_BUFFER_BIT|GL_DEPTH_BUFFER_BIT);nvgBeginFrame(vg,512,512,1);for(int i=0;i<9;i++){float a=i*6.2831853/9+frame*.18;nvgSave(vg);nvgTranslate(vg,256+cos(a)*142,256+sin(a)*142);nvgRotate(vg,a);nvgBeginPath(vg);nvgRoundedRect(vg,-62,-22,124,44,12);NVGpaint paint=nvgLinearGradient(vg,-62,0,62,0,nvgRGB(87,216,198),nvgRGB(173,155,255));nvgFillPaint(vg,paint);nvgFill(vg);nvgStrokeWidth(vg,2+frame*2);nvgStrokeColor(vg,nvgRGBA(255,188,120,220));nvgStroke(vg);nvgRestore(vg);}nvgBeginPath(vg);nvgMoveTo(vg,50,350);nvgBezierTo(vg,140,70+frame*50,372,440-frame*50,462,160);nvgStrokeWidth(vg,8);nvgLineCap(vg,NVG_ROUND);nvgStrokeColor(vg,nvgRGB(255,188,120));nvgStroke(vg);nvgEndFrame(vg);glFinish();glReadPixels(0,0,512,512,GL_RGBA,GL_UNSIGNED_BYTE,pixels);if(glGetError()!=GL_NO_ERROR)return 5;char path[4096];snprintf(path,sizeof(path),"%s/render-%d.ppm",argv[1],frame);FILE*f=fopen(path,"wb");if(!f)return 6;fprintf(f,"P6\n512 512\n255\n");for(int y=511;y>=0;y--)for(int x=0;x<512;x++)fwrite(pixels+(y*512+x)*4,1,3,f);fclose(f);}free(pixels);nvgDeleteGL3(vg);glDeleteRenderbuffers(1,&stencil);glDeleteTextures(1,&tex);glDeleteFramebuffers(1,&fb);CGLSetCurrentContext(NULL);CGLDestroyContext(context);puts("PASS native NanoVG GL3 renders");return 0;}
